mapper.select:
WITH player_data AS ( SELECT md.match_id, (p->>'account_id')::bigint + 76561197960265728 AS steam_id, (p->>'win')::boolean AS win, p->'purchase_log' AS purchase_log FROM match_detail md, LATERAL jsonb_array_elements(md.raw_json::jsonb->'players') AS p WHERE md.sync_status = 2 AND md.raw_json IS NOT NULL AND p->>'account_id' IS NOT NULL AND p->'purchase_log' IS NOT NULL AND p->>'purchase_log' != 'null' AND jsonb_typeof(p->'purchase_log') = 'array'
AND (p->>'account_id')::bigint + 76561197960265728 = #{steamId}::bigint
), starting_items AS ( SELECT match_id, steam_id, win, jsonb_agg(DISTINCT entry->>'key' ORDER BY entry->>'key') AS items FROM player_data, LATERAL jsonb_array_elements(purchase_log) AS entry WHERE (entry->>'time')::int <= 0 AND entry->>'key' NOT IN (${excludeItems}) GROUP BY match_id, steam_id, win ) SELECT items::text AS items_json, COUNT(*)::bigint AS games, SUM(CASE WHEN win THEN 1 ELSE 0 END)::bigint AS wins FROM starting_items WHERE items IS NOT NULL AND jsonb_array_length(items) > 0 GROUP BY items ORDER BY COUNT(*) DESC LIMIT 30

SELECT item_id, COUNT(*)::bigint AS games, SUM(CASE WHEN win THEN 1 ELSE 0 END)::bigint AS wins, ROUND(100.0 * SUM(CASE WHEN win THEN 1 ELSE 0 END) / COUNT(*), 1) AS win_rate FROM ( SELECT DISTINCT md.match_id, (p->>'account_id')::bigint + 76561197960265728 AS steam_id, (p->>'hero_id')::int AS hero_id, (p->>'win')::boolean AS win, item.value::int AS item_id FROM match_detail md, LATERAL jsonb_array_elements(md.raw_json::jsonb->'players') AS p, LATERAL jsonb_array_elements( jsonb_build_array(p->'item_0', p->'item_1', p->'item_2', p->'item_3', p->'item_4', p->'item_5') ) AS item WHERE md.sync_status = 2 AND md.raw_json IS NOT NULL AND p->>'account_id' IS NOT NULL AND item.value IS NOT NULL AND item.value::text != '0' AND item.value::text != '' AND item.value::text != 'null'
AND (p->>'account_id')::bigint + 76561197960265728 = #{steamId}::bigint
AND (p->>'hero_id')::int = #{heroId}
) t GROUP BY item_id ORDER BY COUNT(*) DESC LIMIT 100

SELECT COUNT(*)::bigint AS total_games, SUM(CASE WHEN win THEN 1 ELSE 0 END)::bigint AS total_wins FROM ( SELECT DISTINCT md.match_id, (p->>'win')::boolean AS win FROM match_detail md, LATERAL jsonb_array_elements(md.raw_json::jsonb->'players') AS p WHERE md.sync_status = 2 AND md.raw_json IS NOT NULL AND p->>'account_id' IS NOT NULL
AND (p->>'account_id')::bigint + 76561197960265728 = #{steamId}::bigint
AND (p->>'hero_id')::int = #{heroId}
) t

WITH player_data AS ( SELECT md.match_id, (p->>'account_id')::bigint + 76561197960265728 AS steam_id, (p->>'hero_id')::int AS hero_id, (p->>'win')::boolean AS win, p->'purchase_log' AS purchase_log FROM match_detail md, LATERAL jsonb_array_elements(md.raw_json::jsonb->'players') AS p WHERE md.sync_status = 2 AND md.raw_json IS NOT NULL AND p->>'account_id' IS NOT NULL AND p->'purchase_log' IS NOT NULL AND p->>'purchase_log' != 'null' AND jsonb_typeof(p->'purchase_log') = 'array'
AND (p->>'account_id')::bigint + 76561197960265728 = #{steamId}::bigint
AND (p->>'hero_id')::int = #{heroId}
), purchased_items AS ( SELECT match_id, steam_id, win, entry->>'key' AS item_key, (entry->>'time')::int AS purchase_time, ROW_NUMBER() OVER ( PARTITION BY match_id, steam_id ORDER BY (entry->>'time')::int ) AS rn FROM player_data, LATERAL jsonb_array_elements(purchase_log) AS entry WHERE (entry->>'time')::int > 0 -- exclude starting items AND entry->>'key' NOT IN (${excludeItems}) ), build_sequences AS ( SELECT match_id, steam_id, win, jsonb_agg(item_key ORDER BY purchase_time) AS items, jsonb_agg(purchase_time ORDER BY purchase_time) AS times, COUNT(*) AS item_count FROM purchased_items WHERE rn <= #{topN} GROUP BY match_id, steam_id, win ) SELECT items::text AS items_json, times::text AS times_json, COUNT(*)::bigint AS games, SUM(CASE WHEN win THEN 1 ELSE 0 END)::bigint AS wins, ROUND(AVG(item_count), 1) AS avg_items, ROUND(AVG((times->>0)::int), 0) AS avg_first_time FROM build_sequences WHERE jsonb_array_length(items) >= 2 GROUP BY items, times ORDER BY COUNT(*) DESC LIMIT 20
